  1→/**
  2→ * Shared type definitions for the thos dashboard.
  3→ *
  4→ * Three categories:
  5→ * 1. **Claude NDJSON protocol** — messages the Claude CLI sends over its
  6→ *    `--sdk-url` WebSocket connection (CLI → WS server).
  7→ * 2. **Browser ↔ Server** — messages exchanged between the React client
  8→ *    and the standalone WS relay server.
  9→ * 3. **UI state** — view-model types consumed by React components.
 10→ */
 11→
 12→// ── Claude NDJSON protocol messages (CLI → server) ────────────────────────
 13→
 14→/**
 15→ * Sent once after the first user prompt is received. Contains session
 16→ * metadata like the model name, working directory, and available tools.
 17→ */
 18→export interface ClaudeSystemInit {
 19→  type: "system";
 20→  subtype: "init";
 21→  session_id: string;
 22→  tools: unknown[];
 23→  mcp_servers: unknown[];
 24→  model: string;
 25→  cwd: string;
 26→}
 27→
 28→/**
 29→ * An assistant turn. `message.content` is an array of content blocks
 30→ * (text, tool_use, tool_result) that may arrive incrementally — each
 31→ * NDJSON line is a complete snapshot of the message so far.
 32→ */
 33→export interface ClaudeAssistant {
 34→  type: "assistant";
 35→  message: {
 36→    id: string;
 37→    role: "assistant";
 38→    content: AssistantContentBlock[];
 39→    model: string;
 40→    stop_reason: string | null;
 41→  };
 42→  session_id: string;
 43→}
 44→
 45→/** A single content block inside an assistant message. */
 46→export type AssistantContentBlock =
 47→  | { type: "text"; text: string }
 48→  | { type: "tool_use"; id: string; name: string; input: Record<string, unknown> }
 49→  | { type: "tool_result"; tool_use_id: string; content: string };
 50→
 51→/**
 52→ * Terminal message for a session. Includes cost/duration metrics.
 53→ * `is_error` is true when `subtype` is `"error"`.
 54→ */
 55→export interface ClaudeResult {
 56→  type: "result";
 57→  subtype: "success" | "error";
 58→  result?: string;
 59→  error?: string;
 60→  session_id: string;
 61→  cost_usd: number;
 62→  duration_ms: number;
 63→  duration_api_ms: number;
 64→  is_error: boolean;
 65→  num_turns: number;
 66→}
 67→
 68→/**
 69→ * Claude is requesting permission to execute a tool. The dashboard must
 70→ * reply with a `control_response` (allow / deny) before the CLI proceeds.
 71→ *
 72→ * Wire format uses a nested `request` object with `request_id` at the
 73→ * top level for correlation (matches Companion protocol docs).
 74→ */
 75→export interface ClaudeControlRequest {
 76→  type: "control_request";
 77→  request_id: string;
 78→  request: {
 79→    subtype: "can_use_tool";
 80→    tool_name: string;
 81→    input: Record<string, unknown>;
 82→    tool_use_id?: string;
 83→    description?: string;
 84→  };
 85→  session_id?: string;
 86→}
 87→
 88→/**
 89→ * Hook lifecycle events emitted during CLI startup. `hook_response` is
 90→ * the signal that the CLI is ready to receive the first user prompt.
 91→ */
 92→export interface ClaudeSystemHook {
 93→  type: "system";
 94→  subtype: "hook_started" | "hook_response";
 95→  session_id?: string;
 96→}
 97→
 98→/** Discriminated union of all known Claude NDJSON message shapes. */
 99→export type ClaudeMessage =
100→  | ClaudeSystemInit
101→  | ClaudeAssistant
102→  | ClaudeResult
103→  | ClaudeControlRequest
104→  | ClaudeSystemHook
105→  | { type: string; subtype?: string; [key: string]: unknown };
106→
107→// ── Browser ↔ Server messages ─────────────────────────────────────────────
108→
109→/** Browser asks the server to spawn a new Claude CLI process. */
110→export interface BrowserSpawn {
111→  type: "spawn";
112→  prompt: string;
113→}
114→
115→/** Browser sends a follow-up message to an already-running Claude session. */
116→export interface BrowserSendMessage {
117→  type: "send_message";
118→  agentId: string;
119→  content: string;
120→}
121→
122→/** Browser responds to a tool approval request (allow or deny). */
123→export interface BrowserControlResponse {
124→  type: "control_response";
125→  agentId: string;
126→  request_id: string;
127→  allow: boolean;
128→}
129→
130→/** Union of all messages the browser can send to the WS server. */
131→export type BrowserMessage = BrowserSpawn | BrowserSendMessage | BrowserControlResponse;
132→
133→/** Server relays a raw Claude NDJSON message to the browser. */
134→export interface ServerRelay {
135→  type: "relay";
136→  agentId: string;
137→  message: ClaudeMessage;
138→}
139→
140→/** Server notifies the browser of an agent status change. */
141→export interface ServerStatus {
142→  type: "status";
143→  agentId: string;
144→  status: AgentStatus;
145→}
146→
147→/** Server reports an error (e.g. no active session, process crash). */
148→export interface ServerError {
149→  type: "error";
150→  agentId: string;
151→  error: string;
152→}
153→
154→/** Summary of an agent for the sidebar. */
155→export interface AgentInfo {
156→  agentId: string;
157→  status: AgentStatus;
158→  tmuxSession: string | null;
159→  label: string;
160→  createdAt: number;
161→}
162→
163→/** Server sends the full list of agents after every state change. */
164→export interface ServerAgentList {
165→  type: "agent_list";
166→  agents: AgentInfo[];
167→}
168→
169→/** Server confirms a new agent was spawned and assigns its ID. */
170→export interface ServerSpawned {
171→  type: "spawned";
172→  agentId: string;
173→}
174→
175→/** Server replays full message history for an agent on browser connect. */
176→export interface ServerMessageHistory {
177→  type: "message_history";
178→  agentId: string;
179→  messages: ServerMessage[];
180→}
181→
182→/** CLI WebSocket disconnected (process may have crashed or exited). */
183→export interface ServerCliDisconnected {
184→  type: "cli_disconnected";
185→  agentId: string;
186→}
187→
188→/** CLI WebSocket reconnected (e.g. after relaunch with --resume). */
189→export interface ServerCliConnected {
190→  type: "cli_connected";
191→  agentId: string;
192→}
193→
194→/** Union of all messages the WS server can send to the browser. */
195→export type ServerMessage =
196→  | ServerRelay
197→  | ServerStatus
198→  | ServerError
199→  | ServerAgentList
200→  | ServerSpawned
201→  | ServerMessageHistory
202→  | ServerCliDisconnected
203→  | ServerCliConnected;
204→
205→// ── UI state ──────────────────────────────────────────────────────────────
206→
207→/**
208→ * Lifecycle states of the Claude agent process:
209→ * - `idle`      — no process running, ready to spawn
210→ * - `spawning`  — process launched, waiting for CLI to connect via WS
211→ * - `connected` — CLI connected and `system/init` received
212→ * - `thinking`  — waiting for assistant response
213→ * - `done`      — `result` message received, process finished
214→ * - `error`     — process crashed or unexpected failure
215→ */
216→export type AgentStatus = "idle" | "spawning" | "connected" | "thinking" | "done" | "disconnected" | "error";
217→
218→export type ChatMessageRole = "user" | "assistant" | "system";
219→
220→/**
221→ * A single entry in the chat message list. System messages include
222→ * session init info and result summaries. Messages with a `controlRequest`
223→ * are rendered as tool-approval cards instead of plain bubbles.
224→ */
225→/** A single option in an AskUserQuestion question. */
226→export interface UserQuestionOption {
227→  label: string;
228→  description?: string;
229→}
230→
231→/** A single question from AskUserQuestion. */
232→export interface UserQuestion {
233→  question: string;
234→  header?: string;
235→  options: UserQuestionOption[];
236→  multiSelect: boolean;
237→}
238→
239→export interface ChatMessage {
240→  id: string;
241→  role: ChatMessageRole;
242→  content: string;
243→  timestamp: number;
244→  /** Present when this message represents a tool approval request. */
245→  controlRequest?: {
246→    id: string;
247→    tool_name: string;
248→    input: Record<string, unknown>;
249→    /** Set to true after the user allows or denies. */
250→    resolved?: boolean;
251→  };
252→  /** Present when this message is an AskUserQuestion control request. */
253→  userQuestion?: {
254→    requestId: string;
255→    questions: UserQuestion[];
256→    resolved?: boolean;
257→  };
258→}
259→

  1→"use client";
  2→
  3→/**
  4→ * React hook that manages the WebSocket connection to the thos relay server.
  5→ *
  6→ * Supports multiple concurrent agents. Each agent has its own status,
  7→ * message history, label, and tmux session name tracked in a Map keyed
  8→ * by agent ID. The `activeAgentId` determines which agent's chat is shown.
  9→ *
 10→ * Resilience features:
 11→ * - Handles `message_history` replay from server on connect/reconnect.
 12→ * - Handles `cli_disconnected` / `cli_connected` events.
 13→ * - Deduplicates messages using a per-agent Set of seen message IDs.
 14→ * - Robust reconnection guard (clears previous timer before scheduling).
 15→ */
 16→
 17→import { useCallback, useEffect, useMemo, useRef, useState } from "react";
 18→import type {
 19→  AgentInfo,
 20→  AgentStatus,
 21→  ChatMessage,
 22→  ClaudeAssistant,
 23→  ClaudeControlRequest,
 24→  ClaudeMessage,
 25→  ClaudeResult,
 26→  ClaudeSystemInit,
 27→  ServerMessage,
 28→  ServerMessageHistory,
 29→  UserQuestion,
 30→} from "@/lib/types";
 31→
 32→const WS_URL = "ws://localhost:9900/browser";
 33→
 34→/** Per-agent client state. */
 35→export interface AgentClientState {
 36→  status: AgentStatus;
 37→  messages: ChatMessage[];
 38→  /** Raw Claude NDJSON messages for debug view. */
 39→  rawMessages: ClaudeMessage[];
 40→  label: string;
 41→  tmuxSession: string | null;
 42→  createdAt: number;
 43→}
 44→
 45→/**
 46→ * Extract displayable text from a Claude assistant message.
 47→ * Content blocks may be text, tool_use, or tool_result — each is
 48→ * handled defensively since the array structure can vary.
 49→ */
 50→function extractText(msg: ClaudeAssistant): string {
 51→  const blocks = msg.message?.content;
 52→  if (!blocks || !Array.isArray(blocks)) return "";
 53→  return blocks
 54→    .map((b) => {
 55→      if (b.type === "text") return b.text;
 56→      if (b.type === "tool_use") return `[tool_use: ${b.name}]`;
 57→      if (b.type === "tool_result") return `[tool_result: ${b.content}]`;
 58→      return "";
 59→    })
 60→    .filter(Boolean)
 61→    .join("\n");
 62→}
 63→
 64→/** Module-level counter for generating unique message IDs. */
 65→let msgCounter = 0;
 66→function nextId() {
 67→  return `msg-${Date.now()}-${++msgCounter}`;
 68→}
 69→
 70→/**
 71→ * Convert a server relay message into a ChatMessage, or null if it shouldn't be displayed.
 72→ * Used both for live messages and for replaying message_history.
 73→ */
 74→function relayChatMessage(agentId: string, relayMsg: ServerMessage): ChatMessage | null {
 75→  if (relayMsg.type === "relay") {
 76→    const msg = relayMsg.message;
 77→
 78→    if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
 79→      const init = msg as ClaudeSystemInit;
 80→      return {
 81→        id: nextId(),
 82→        role: "system",
 83→        content: `Session started — model: ${init.model}, cwd: ${init.cwd}`,
 84→        timestamp: Date.now(),
 85→      };
 86→    }
 87→
 88→    if (msg.type === "assistant") {
 89→      const text = extractText(msg as ClaudeAssistant);
 90→      if (text) {
 91→        return {
 92→          id: nextId(),
 93→          role: "assistant",
 94→          content: text,
 95→          timestamp: Date.now(),
 96→        };
 97→      }
 98→      return null;
 99→    }
100→
101→    if (msg.type === "result") {
102→      const result = msg as ClaudeResult;
103→      const summary = result.is_error
104→        ? `Error: ${result.error}`
105→        : `Done — ${result.num_turns ?? "?"} turns, $${(result.cost_usd ?? 0).toFixed(4)}, ${((result.duration_ms ?? 0) / 1000).toFixed(1)}s`;
106→      return {
107→        id: nextId(),
108→        role: "system",
109→        content: summary,
110→        timestamp: Date.now(),
111→      };
112→    }
113→
114→    if (msg.type === "control_request") {
115→      const cr = msg as ClaudeControlRequest;
116→
117→      // AskUserQuestion gets its own UI instead of generic Allow/Deny
118→      if (cr.request.tool_name === "AskUserQuestion") {
119→        const input = cr.request.input as { questions?: UserQuestion[] };
120→        const questions = Array.isArray(input.questions) ? input.questions : [];
121→        return {
122→          id: nextId(),
123→          role: "system",
124→          content: "Question from Claude",
125→          timestamp: Date.now(),
126→          userQuestion: {
127→            requestId: cr.request_id,
128→            questions,
129→          },
130→        };
131→      }
132→
133→      return {
134→        id: nextId(),
135→        role: "system",
136→        content: `Tool approval requested: ${cr.request.tool_name}`,
137→        timestamp: Date.now(),
138→        controlRequest: {
139→          id: cr.request_id,
140→          tool_name: cr.request.tool_name,
141→          input: cr.request.input,
142→        },
143→      };
144→    }
145→  }
146→
147→  if (relayMsg.type === "error" && relayMsg.agentId === agentId) {
148→    return {
149→      id: nextId(),
150→      role: "system",
151→      content: `Error: ${relayMsg.error}`,
152→      timestamp: Date.now(),
153→    };
154→  }
155→
156→  return null;
157→}
158→
159→export function useWebSocket() {
160→  const wsRef = useRef<WebSocket | null>(null);
161→  const reconnectTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
162→  const [connected, setConnected] = useState(false);
163→
164→  // Multi-agent state
165→  const [agents, setAgents] = useState<Map<string, AgentClientState>>(new Map());
166→  const [agentOrder, setAgentOrder] = useState<string[]>([]);
167→  const [activeAgentId, setActiveAgentId] = useState<string | null>(null);
168→
169→  // Per-agent deduplication: track count of processed messages per agent
170→  // to avoid duplicating messages already in local state during history replay.
171→  const processedCountRef = useRef<Map<string, number>>(new Map());
172→
173→  /** Immutably update a single agent's state in the Map. */
174→  const updateAgent = useCallback(
175→    (agentId: string, updater: (prev: AgentClientState) => AgentClientState) => {
176→      setAgents((prev) => {
177→        const existing = prev.get(agentId);
178→        if (!existing) return prev;
179→        const next = new Map(prev);
180→        next.set(agentId, updater(existing));
181→        return next;
182→      });
183→    },
184→    []
185→  );
186→
187→  const connect = useCallback(() => {
188→    if (wsRef.current?.readyState === WebSocket.OPEN) return;
189→    if (wsRef.current) {
190→      wsRef.current.close();
191→      wsRef.current = null;
192→    }
193→
194→    const ws = new WebSocket(WS_URL);
195→    wsRef.current = ws;
196→
197→    ws.onopen = () => setConnected(true);
198→
199→    ws.onclose = () => {
200→      setConnected(false);
201→      wsRef.current = null;
202→      // Reconnection guard: clear any existing timer before scheduling
203→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
204→      reconnectTimer.current = setTimeout(() => connect(), 2000);
205→    };
206→
207→    ws.onerror = () => {
208→      // onclose will fire after onerror, which triggers reconnect
209→    };
210→
211→    ws.onmessage = (event) => {
212→      let data: ServerMessage;
213→      try {
214→        data = JSON.parse(event.data as string);
215→      } catch {
216→        return;
217→      }
218→
219→      // ── message_history: replay full history from server ──
220→      if (data.type === "message_history") {
221→        const historyMsg = data as ServerMessageHistory;
222→        const agentId = historyMsg.agentId;
223→        const serverMessages = historyMsg.messages;
224→
225→        // Convert all server messages to ChatMessages + extract raw Claude messages
226→        const chatMessages: ChatMessage[] = [];
227→        const rawMessages: ClaudeMessage[] = [];
228→        for (const sm of serverMessages) {
229→          if (sm.type === "relay") {
230→            rawMessages.push(sm.message);
231→          }
232→          const cm = relayChatMessage(agentId, sm);
233→          if (cm) chatMessages.push(cm);
234→        }
235→
236→        // Skip messages already processed locally (dedup)
237→        const alreadyProcessed = processedCountRef.current.get(agentId) ?? 0;
238→        const newMessages = chatMessages.slice(alreadyProcessed);
239→
240→        if (newMessages.length > 0) {
241→          setAgents((prev) => {
242→            const existing = prev.get(agentId);
243→            if (!existing) {
244→              // Agent not yet in local state — create it
245→              const next = new Map(prev);
246→              next.set(agentId, {
247→                status: "idle",
248→                messages: chatMessages, // use full history for new agent
249→                rawMessages,
250→                label: "",
251→                tmuxSession: null,
252→                createdAt: 0,
253→              });
254→              return next;
255→            }
256→            // Replace messages with full server history (source of truth)
257→            const next = new Map(prev);
258→            next.set(agentId, { ...existing, messages: chatMessages, rawMessages });
259→            return next;
260→          });
261→        }
262→
263→        processedCountRef.current.set(agentId, chatMessages.length);
264→        return;
265→      }
266→
267→      // ── cli_disconnected: show system message ──
268→      if (data.type === "cli_disconnected") {
269→        updateAgent(data.agentId, (prev) => ({
270→          ...prev,
271→          status: "disconnected",
272→          messages: [
273→            ...prev.messages,
274→            {
275→              id: nextId(),
276→              role: "system",
277→              content: "CLI disconnected — attempting reconnect...",
278→              timestamp: Date.now(),
279→            },
280→          ],
281→        }));
282→        return;
283→      }
284→
285→      // ── cli_connected: show system message ──
286→      if (data.type === "cli_connected") {
287→        updateAgent(data.agentId, (prev) => ({
288→          ...prev,
289→          messages: [
290→            ...prev.messages,
291→            {
292→              id: nextId(),
293→              role: "system",
294→              content: "CLI reconnected",
295→              timestamp: Date.now(),
296→            },
297→          ],
298→        }));
299→        return;
300→      }
301→
302→      // ── agent_list: reconcile sidebar state from server ──
303→      if (data.type === "agent_list") {
304→        const serverAgents = data.agents as AgentInfo[];
305→        setAgents((prev) => {
306→          const next = new Map(prev);
307→          const serverIds = new Set(serverAgents.map((a) => a.agentId));
308→
309→          // Update or add agents from server
310→          for (const info of serverAgents) {
311→            const existing = next.get(info.agentId);
312→            if (existing) {
313→              next.set(info.agentId, {
314→                ...existing,
315→                status: info.status,
316→                tmuxSession: info.tmuxSession,
317→                label: info.label,
318→              });
319→            } else {
320→              next.set(info.agentId, {
321→                status: info.status,
322→                messages: [],
323→                rawMessages: [],
324→                label: info.label,
325→                tmuxSession: info.tmuxSession,
326→                createdAt: info.createdAt,
327→              });
328→            }
329→          }
330→
331→          // Remove agents no longer on the server
332→          for (const id of next.keys()) {
333→            if (!serverIds.has(id)) {
334→              next.delete(id);
335→            }
336→          }
337→
338→          return next;
339→        });
340→        setAgentOrder(serverAgents.map((a) => a.agentId));
341→        return;
342→      }
343→
344→      // ── spawned: auto-select the newly created agent ──
345→      if (data.type === "spawned") {
346→        setActiveAgentId(data.agentId);
347→        return;
348→      }
349→
350→      // ── status: update a specific agent's status ──
351→      if (data.type === "status") {
352→        updateAgent(data.agentId, (prev) => ({ ...prev, status: data.status }));
353→        return;
354→      }
355→
356→      // ── error: append to agent's message list ──
357→      if (data.type === "error") {
358→        updateAgent(data.agentId, (prev) => ({
359→          ...prev,
360→          messages: [
361→            ...prev.messages,
362→            {
363→              id: nextId(),
364→              role: "system",
365→              content: `Error: ${data.error}`,
366→              timestamp: Date.now(),
367→            },
368→          ],
369→        }));
370→        // Track processed count for dedup
371→        processedCountRef.current.set(
372→          data.agentId,
373→          (processedCountRef.current.get(data.agentId) ?? 0) + 1
374→        );
375→        return;
376→      }
377→
378→      // ── relay: append claude message to agent's history ──
379→      if (data.type === "relay") {
380→        const agentId = data.agentId;
381→        const rawMsg = data.message;
382→        const chatMsg = relayChatMessage(agentId, data);
383→
384→        updateAgent(agentId, (prev) => ({
385→          ...prev,
386→          rawMessages: [...prev.rawMessages, rawMsg],
387→          messages: chatMsg ? [...prev.messages, chatMsg] : prev.messages,
388→        }));
389→        if (chatMsg) {
390→          // Track processed count for dedup
391→          processedCountRef.current.set(
392→            agentId,
393→            (processedCountRef.current.get(agentId) ?? 0) + 1
394→          );
395→        }
396→        return;
397→      }
398→    };
399→  }, [updateAgent]);
400→
401→  useEffect(() => {
402→    connect();
403→    return () => {
404→      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
405→      wsRef.current?.close();
406→    };
407→  }, [connect]);
408→
409→  const send = useCallback((data: object) => {
410→    if (wsRef.current?.readyState === WebSocket.OPEN) {
411→      wsRef.current.send(JSON.stringify(data));
412→    }
413→  }, []);
414→
415→  const spawnAgent = useCallback(
416→    (prompt: string) => {
417→      send({ type: "spawn", prompt });
418→    },
419→    [send]
420→  );
421→
422→  const sendMessage = useCallback(
423→    (content: string) => {
424→      if (!activeAgentId) return;
425→      // Optimistically add user message to local state
426→      updateAgent(activeAgentId, (prev) => ({
427→        ...prev,
428→        messages: [
429→          ...prev.messages,
430→          {
431→            id: nextId(),
432→            role: "user",
433→            content,
434→            timestamp: Date.now(),
435→          },
436→        ],
437→      }));
438→      send({ type: "send_message", agentId: activeAgentId, content });
439→    },
440→    [send, activeAgentId, updateAgent]
441→  );
442→
443→  const respondToControl = useCallback(
444→    (requestId: string, allow: boolean) => {
445→      if (!activeAgentId) return;
446→      send({ type: "control_response", agentId: activeAgentId, request_id: requestId, allow });
447→      updateAgent(activeAgentId, (prev) => ({
448→        ...prev,
449→        messages: prev.messages.map((m) =>
450→          m.controlRequest?.id === requestId
451→            ? { ...m, controlRequest: { ...m.controlRequest, resolved: true } }
452→            : m
453→        ),
454→      }));
455→    },
456→    [send, activeAgentId, updateAgent]
457→  );
458→
459→  /** Respond to an AskUserQuestion control request with the user's selections. */
460→  const respondToUserQuestion = useCallback(
461→    (requestId: string, answers: Record<string, string>) => {
462→      if (!activeAgentId) return;
463→      send({
464→        type: "control_response",
465→        agentId: activeAgentId,
466→        request_id: requestId,
467→        allow: true,
468→        answers,
469→      });
470→      updateAgent(activeAgentId, (prev) => ({
471→        ...prev,
472→        messages: prev.messages.map((m) =>
473→          m.userQuestion?.requestId === requestId
474→            ? { ...m, userQuestion: { ...m.userQuestion, resolved: true } }
475→            : m
476→        ),
477→      }));
478→    },
479→    [send, activeAgentId, updateAgent]
480→  );
481→
482→  // Derived values for the active agent
483→  const activeAgent = activeAgentId ? agents.get(activeAgentId) : undefined;
484→  const activeStatus = useMemo<AgentStatus>(
485→    () => activeAgent?.status ?? "idle",
486→    [activeAgent?.status]
487→  );
488→  const activeMessages = useMemo<ChatMessage[]>(
489→    () => activeAgent?.messages ?? [],
490→    [activeAgent?.messages]
491→  );
492→  const activeRawMessages = useMemo<ClaudeMessage[]>(
493→    () => activeAgent?.rawMessages ?? [],
494→    [activeAgent?.rawMessages]
495→  );
496→
497→  return {
498→    connected,
499→    agents,
500→    agentOrder,
501→    activeAgentId,
502→    setActiveAgentId,
503→    activeStatus,
504→    activeMessages,
505→    activeRawMessages,
506→    spawnAgent,
507→    sendMessage,
508→    respondToControl,
509→    respondToUserQuestion,
510→  };
511→}
