156→function RawMessage({ message, index }: { message: ClaudeMessage; index: number }) {
157→  const [expanded, setExpanded] = useState(false);
158→  const subtype = (message as { subtype?: string }).subtype;
159→  const typeLabel = subtype ? `${message.type}/${subtype}` : message.type;
160→  const colorClass = TYPE_COLORS[message.type] ?? "text-muted-foreground";
161→
162→  return (
163→    <div className="font-mono text-[11px] leading-relaxed">
164→      <button
165→        onClick={() => setExpanded((v) => !v)}
166→        className="flex w-full items-center gap-2 rounded px-2 py-1 text-left hover:bg-muted/50 transition-colors"
167→      >
168→        <span className="text-muted-foreground w-6 shrink-0 text-right">{index}</span>
169→        <span className={colorClass}>{typeLabel}</span>
170→        <span className="text-muted-foreground">{expanded ? "▼" : "▶"}</span>
171→      </button>
172→      {expanded && (
173→        <pre className="ml-10 overflow-x-auto rounded bg-muted/30 p-2 text-[10px] text-muted-foreground whitespace-pre-wrap break-all">
174→          {JSON.stringify(message, null, 2)}
175→        </pre>
176→      )}
177→    </div>
178→  );
179→}
