  1→/**
  2→ * Standalone WebSocket relay server for the thos dashboard.
  3→ *
  4→ * Runs on port 9900 alongside Next.js (started via `concurrently` in the
  5→ * `dev` script). It cannot be a Next.js API route because API routes don't
  6→ * support persistent WebSocket connections.
  7→ *
  8→ * ## Architecture
  9→ *
 10→ * Two WebSocket path families:
 11→ * - `/browser`          — the React dashboard connects here (supports multiple tabs).
 12→ * - `/claude/:agentId`  — each Claude CLI connects here (passed as `--sdk-url`).
 13→ *
 14→ * The server supports multiple concurrent agents, each tracked in the
 15→ * `agents` Map keyed by a short random ID.
 16→ *
 17→ * ## Resilience features
 18→ *
 19→ * - **Server-side message history** — every relay message is stored per-agent.
 20→ * - **File persistence** — agent state + history persisted to disk, survives restarts.
 21→ * - **Multi-browser** — multiple tabs can connect simultaneously.
 22→ * - **CLI relaunch** — dead agents with a sessionId are relaunched with `--resume`.
 23→ * - **Message queuing** — messages sent while CLI is disconnected are queued and flushed on reconnect.
 24→ * - **Disconnect notifications** — browser is notified of CLI disconnect/reconnect.
 25→ *
 26→ * ## Message flow
 27→ *
 28→ * 1. Browser sends `{ type: "spawn", prompt }`.
 29→ * 2. Server creates agent entry, spawns `claude --sdk-url ws://localhost:9900/claude/<agentId>`.
 30→ * 3. CLI connects on `/claude/<agentId>`, sends `system/hook_started` then `system/hook_response`.
 31→ * 4. On `hook_response`, server forwards the pending prompt to the CLI.
 32→ * 5. CLI sends `system/init`, then `assistant` messages, then `result`.
 33→ * 6. All CLI messages are relayed to the browser as `{ type: "relay", agentId, message }`.
 34→ * 7. `control_request` messages (tool approval) are relayed to the browser;
 35→ *    the browser's `control_response` (with `agentId`) is forwarded back to the right CLI.
 36→ */
 37→import { WebSocketServer, WebSocket } from "ws";
 38→import { execSync, spawn } from "child_process";
 39→import { randomBytes } from "crypto";
 40→import type { IncomingMessage } from "http";
 41→import type {
 42→  BrowserMessage,
 43→  ClaudeMessage,
 44→  ServerMessage,
 45→  AgentStatus,
 46→  AgentInfo,
 47→} from "../lib/types";
 48→import { SessionStore, type PersistedAgent } from "./session-store";
 49→
 50→const PORT = 9900;
 51→const TMUX_SESSION_PREFIX = "thos-agent";
 52→const wss = new WebSocketServer({ port: PORT });
 53→const store = new SessionStore();
 54→
 55→// ── Multi-agent state ──────────────────────────────────────────────────────
 56→
 57→interface AgentState {
 58→  agentId: string;
 59→  claudeSocket: WebSocket | null;
 60→  tmuxSession: string | null;
 61→  pendingPrompt: string | null;
 62→  status: AgentStatus;
 63→  label: string;
 64→  createdAt: number;
 65→  /** Captured from system/init, used in subsequent user messages and --resume. */
 66→  sessionId: string | null;
 67→  /** Stores control_request inputs keyed by request_id, for building control_responses. */
 68→  pendingControlRequests: Map<string, Record<string, unknown>>;
 69→  /** All messages sent to the browser for this agent (source of truth). */
 70→  messageHistory: ServerMessage[];
 71→  /** Messages queued while CLI is disconnected, flushed on reconnect. */
 72→  pendingMessages: string[];
 73→}
 74→
 75→const agents = new Map<string, AgentState>();
 76→
 77→/** All active browser connections (supports multiple tabs). */
 78→const browserSockets = new Set<WebSocket>();
 79→
 80→/** Generate a short random agent ID. */
 81→function newAgentId(): string {
 82→  return randomBytes(4).toString("hex");
 83→}
 84→
 85→// ── Persistence helpers ────────────────────────────────────────────────────
 86→
 87→/** Build a PersistedAgent snapshot from live state. */
 88→function toPersistedAgent(agent: AgentState): PersistedAgent {
 89→  return {
 90→    id: agent.agentId,
 91→    state: {
 92→      agentId: agent.agentId,
 93→      status: agent.status,
 94→      tmuxSession: agent.tmuxSession,
 95→      label: agent.label,
 96→      createdAt: agent.createdAt,
 97→      sessionId: agent.sessionId,
 98→    },
 99→    messageHistory: agent.messageHistory,
100→  };

