 1→"use client";
 2→
 3→import { useEffect, useRef, useState } from "react";
 4→
 5→interface ScrambleTextProps {
 6→  text: string;
 7→  characters?: string;
 8→  duration?: number;
 9→  delay?: number;
10→  trigger?: boolean;
11→  className?: string;
12→}
13→
14→export function ScrambleText({
15→  text,
16→  characters = "[]░▒▓█▀▄⣿",
17→  duration = 600,
18→  delay = 0,
19→  trigger = true,
20→  className,
21→}: ScrambleTextProps) {
22→  const [display, setDisplay] = useState("");
23→  const frameRef = useRef(0);
24→  const lastTickRef = useRef(0);
25→  const resolveTimesRef = useRef<number[]>([]);
26→
27→  useEffect(() => {
28→    if (!trigger) {
29→      setDisplay(text);
30→      return;
31→    }
32→
33→    // each character gets a resolve time: positional wave + randomness
34→    resolveTimesRef.current = Array.from({ length: text.length }, (_, i) => {
35→      const posWeight = i / Math.max(text.length - 1, 1);
36→      const rand = Math.random() * 0.5;
37→      return delay + duration * (posWeight * 0.5 + rand * 0.5);
38→    });
39→
40→    const start = performance.now();
41→    lastTickRef.current = 0;
42→
43→    function tick(now: number) {
44→      const elapsed = now - start;
45→
46→      // throttle to ~50ms for the choppy scramble feel
47→      if (now - lastTickRef.current < 50) {
48→        frameRef.current = requestAnimationFrame(tick);
49→        return;
50→      }
51→      lastTickRef.current = now;
52→
53→      const chars = text.split("").map((char, i) => {
54→        if (char === " ") return " ";
55→        if (elapsed >= resolveTimesRef.current[i]) return char;
56→        return characters[Math.floor(Math.random() * characters.length)];
57→      });
58→
59→      setDisplay(chars.join(""));
60→
61→      if (resolveTimesRef.current.some((t) => elapsed < t)) {
62→        frameRef.current = requestAnimationFrame(tick);
63→      }
64→    }
65→
66→    frameRef.current = requestAnimationFrame(tick);
67→    return () => cancelAnimationFrame(frameRef.current);
68→  }, [text, characters, duration, delay, trigger]);
69→
70→  return <span className={className}>{display}</span>;
71→}
