  3→/**
  4→ * Main chat interface for the thos dashboard.
  5→ *
  6→ * Composes {@link StatusBar}, a scrollable message list ({@link Message}
  7→ * and {@link ControlRequest} cards), and an input bar. The submit button
  8→ * text toggles between "Spawn" (when idle/done) and "Send" (when an
  9→ * agent session is active). Auto-scrolls on new messages.
 10→ *
 11→ * A toggle in the top-right switches between the processed chat view
 12→ * and a raw JSON view of all Claude NDJSON messages.
 13→ *
 14→ * Receives all data and callbacks via props — the parent page component
 15→ * owns the WebSocket hook and orchestrates multiple agents.
 16→ */
 17→
 18→import { useEffect, useRef, useState } from "react";
 19→import type { AgentStatus, ChatMessage, ClaudeMessage } from "@/lib/types";
 20→import { StatusBar } from "./status-bar";
 21→import { Message } from "./message";
 22→import { ControlRequest } from "./control-request";
 23→import { UserQuestion } from "./user-question";
 24→import { Button } from "@/components/ui/button";
 25→
 26→export function Chat({
 27→  connected,
 28→  status,
 29→  messages,
 30→  rawMessages,
 31→  onSendMessage,
 32→  onSpawnAgent,
 33→  onRespondToControl,
 34→  onRespondToUserQuestion,
 35→}: {
 36→  connected: boolean;
 37→  status: AgentStatus;
 38→  messages: ChatMessage[];
 39→  rawMessages: ClaudeMessage[];
 40→  onSendMessage: (content: string) => void;
 41→  onSpawnAgent: (prompt: string) => void;
 42→  onRespondToControl: (requestId: string, allow: boolean) => void;
 43→  onRespondToUserQuestion: (requestId: string, answers: Record<string, string>) => void;
 44→}) {
 45→  const [input, setInput] = useState("");
 46→  const [showRaw, setShowRaw] = useState(false);
 47→  const scrollRef = useRef<HTMLDivElement>(null);
 48→
 49→  useEffect(() => {
 50→    scrollRef.current?.scrollTo({
 51→      top: scrollRef.current.scrollHeight,
 52→      behavior: "smooth",
 53→    });
 54→  }, [messages, rawMessages, showRaw]);
 55→
 56→  const isActive = status === "connected" || status === "thinking";
 57→
 58→  function handleSubmit(e: React.FormEvent) {
 59→    e.preventDefault();
 60→    const trimmed = input.trim();
 61→    if (!trimmed) return;
 62→
 63→    if (isActive) {
 64→      onSendMessage(trimmed);
 65→    } else {
 66→      onSpawnAgent(trimmed);
 67→    }
 68→    setInput("");
 69→  }
 70→
 71→  return (
 72→    <div className="flex h-full flex-col">
 73→      <div className="relative">
 74→        <StatusBar connected={connected} status={status} />
 75→        <button
 76→          onClick={() => setShowRaw((v) => !v)}
 77→          className={`absolute right-3 top-1/2 -translate-y-1/2 rounded px-2 py-0.5 text-[10px] font-mono transition-colors ${
 78→            showRaw
 79→              ? "bg-foreground text-background"
 80→              : "bg-muted text-muted-foreground hover:bg-muted/80"
 81→          }`}
 82→        >
 83→          {showRaw ? "RAW" : "raw"}
 84→        </button>
 85→      </div>
 86→
 87→      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-2">
 88→        {showRaw ? (
 89→          rawMessages.length === 0 ? (
 90→            <div className="flex h-full items-center justify-center text-sm text-muted-foreground">
 91→              No raw messages yet
 92→            </div>
 93→          ) : (
 94→            <div className="space-y-1">
 95→              {rawMessages.map((msg, i) => (
 96→                <RawMessage key={i} message={msg} index={i} />
 97→              ))}
 98→            </div>
 99→          )
100→        ) : (
101→          <>
102→            {messages.length === 0 && (
103→              <div className="flex h-full items-center justify-center text-sm text-muted-foreground">
104→                Type a prompt to spawn a Claude agent
105→              </div>
106→            )}
107→            {messages.map((msg) =>
108→              msg.userQuestion ? (
109→                <UserQuestion
110→                  key={msg.id}
111→                  message={msg}
112→                  onRespond={onRespondToUserQuestion}
113→                />
114→              ) : msg.controlRequest ? (
115→                <ControlRequest
116→                  key={msg.id}
117→                  message={msg}
118→                  onRespond={onRespondToControl}
119→                />
120→              ) : (
121→                <Message key={msg.id} message={msg} />
122→              )
123→            )}
124→          </>
125→        )}
126→      </div>
127→
128→      <form
129→        onSubmit={handleSubmit}
130→        className="flex gap-2 border-t px-4 py-3"
131→      >
132→        <input
133→          type="text"
134→          value={input}
135→          onChange={(e) => setInput(e.target.value)}
136→          placeholder={isActive ? "Send a follow-up..." : "Enter a prompt to spawn agent..."}
137→          className="flex-1 rounded-md border bg-background px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-ring"
138→        />
139→        <Button type="submit" disabled={!connected || !input.trim()}>
140→          {isActive ? "Send" : "Spawn"}
141→        </Button>
142→      </form>
143→    </div>
144→  );
145→}
