147→/** Badge color per Claude NDJSON message type. */
148→const TYPE_COLORS: Record<string, string> = {
149→  system: "text-yellow-500",
150→  assistant: "text-blue-400",
151→  result: "text-green-500",
152→  control_request: "text-orange-400",
153→  keep_alive: "text-muted-foreground",
