  /** Total number of messages condensed */
  count: number;
  /** Timestamp of the first message in the group */
  timestamp: number;
}

export type DisplayItem = SingleItem | CondensedGroup;

export function condenseMessages(messages: ChatMessage[]): DisplayItem[] {
  const result: DisplayItem[] = [];
  let i = 0;

  while (i < messages.length) {
    const msg = messages[i];

    // Check if this starts a tool-only run
    if (msg.isToolOnly) {
      // Collect consecutive tool-only messages
      const group: ChatMessage[] = [];
      while (i < messages.length && messages[i].isToolOnly) {
        group.push(messages[i]);
        i++;
