          .join(", ");

        const totalCalls = Object.values(toolCounts).reduce((a, b) => a + b, 0);

        result.push({
          kind: "condensed",
          id: `group-${group[0].id}`,
          messages: group,
          summary: `${totalCalls} tool calls (${breakdown})`,
          toolCounts,
          count: group.length,
          timestamp: group[0].timestamp,
        });
      } else {
        // Single tool-only message: show as-is
        result.push({ kind: "single", message: group[0] });
      }
    } else {
      result.push({ kind: "single", message: msg });
      i++;
    }
  }

  return result;
}
```

